type Store struct{ io.Reader }                 // promotion: Read forwards automatically

type Counting struct {
    io.Reader                                  // embedded interface, not a concrete type
    n int64
}

func (c *Counting) Read(p []byte) (int, error) {
    n, err := c.Reader.Read(p)                 // delegate to the wrapped reader
    c.n += int64(n)
    return n, err
}

func WithLogging(log *slog.Logger, next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        start := time.Now()
        next.ServeHTTP(w, r)                    // delegate to the wrapped handler
        log.Info("request", "path", r.URL.Path, "dur", time.Since(start))
    })
}

var handler = WithLogging(logger, WithAuth(auth, routes()))  // order = composition order

